/* global __dirname */
// Vendor the exact WebView runtime so Explore can boot without a CDN.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { Buffer } = require('node:buffer');
async function main() {
  const version = '4.7.1';
  const output = path.resolve(__dirname, '../src/components/map/vendor');
  fs.mkdirSync(output, { recursive: true });
  const files = {};
  for (const name of ['dist/maplibre-gl.js', 'dist/maplibre-gl.css', 'LICENSE.txt']) {
    const response = await fetch(`https://unpkg.com/maplibre-gl@${version}/${name}`);
    if (!response.ok) throw new Error(`Runtime download failed: ${response.status}`);
    files[name] = await response.text();
  }
  fs.writeFileSync(path.join(output, 'maplibreRuntime.ts'),
    '/* eslint-disable */\n// Generated by scripts/prepare-explore-map.cjs. MapLibre GL JS 4.7.1; see LICENSE.txt.\n' +
    `export const mapLibreJavaScript = ${JSON.stringify(files['dist/maplibre-gl.js'].replace(/\/\/# sourceMappingURL=.*$/gm, ''))};\n` +
    `export const mapLibreCss = ${JSON.stringify(files['dist/maplibre-gl.css'])};\n`);
  fs.writeFileSync(path.join(output, 'LICENSE.txt'), files['LICENSE.txt']);
  const logoResponse = await fetch('https://api.maptiler.com/resources/logo.svg');
  if (!logoResponse.ok) throw new Error('Logo download failed');
  const logo = await logoResponse.text();
  if (!logo.includes('<svg')) throw new Error('Unexpected logo response');
  fs.writeFileSync(path.join(output, 'mapTilerLogo.ts'),
    '// Official attribution logo from https://api.maptiler.com/resources/logo.svg\n' +
    `export const mapTilerLogo = ${JSON.stringify(logo)};\n`);
  for (const [name, contents] of Object.entries(files)) {
    console.log(`${name}: ${Buffer.byteLength(contents)} bytes; sha256 ${crypto.createHash('sha256').update(contents).digest('hex')}`);
  }
}
main().catch(() => { console.error('Could not prepare local MapLibre runtime.'); process.exitCode = 1; });
